-- Authored help guides (generated by `fierylib seed help --emit-sql`).
-- Source: fierylib/data/help/*.md. Do not edit by hand; edit the markdown
-- and regenerate.
-- Idempotent: matches on the primary keyword ("HelpEntry" has no unique key),
-- overwriting a legacy entry with the same primary keyword; a re-run changes 0 rows
-- (the UPDATE is skipped when the row already matches).

-- mortal: Mortal mode
DO $do$
DECLARE v_id integer;
BEGIN
  SELECT id INTO v_id FROM "HelpEntry" WHERE keywords[1] = 'mortal' ORDER BY id LIMIT 1;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM "HelpEntry" WHERE 'mortal' = ANY(keywords) ORDER BY id LIMIT 1;
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO "HelpEntry"
      (keywords, title, content, min_level, category, usage, source_file, updated_at)
    VALUES (
      ARRAY['mortal', 'mortal mode']::text[],
      'Mortal mode',
      $help$MORTAL switches you between playing as an immortal and playing under mortal
rules, so you can retest what players experience. Type it once to turn mortal
mode on and again to turn it off. While it is on your prompt shows <mortal>.

While mortal mode is on:
  - spells use your spell slots and recover over time like anyone else's
  - you must know a spell or skill, and meet its class and alignment limits,
    to use it
  - gear restrictions (class, race, alignment, no-take) apply to you
  - carry weight and capacity limits apply
  - spells have a cast wind-up and you are held back after a broken-off cast
  - spells that cannot be cast in combat are refused while you fight

Your rank, commands and permissions do not change: goto, stat, users and every
other staff command still work, and you still see and enter god zones. Mortal
mode is not saved: it survives a dropped link while you are fighting (you
reconnect to the same character) and taking over your own body, but a normal
quit or logout resets it, so you start each fresh login with it off.

See also: HOLYLIGHT, SPELLS, SCORE$help$,
      100,
      'command',
      'mortal',
      'data/help/mortal.md',
      now()
    );
  ELSE
    UPDATE "HelpEntry" SET
      keywords = ARRAY['mortal', 'mortal mode']::text[],
      title = 'Mortal mode',
      content = $help$MORTAL switches you between playing as an immortal and playing under mortal
rules, so you can retest what players experience. Type it once to turn mortal
mode on and again to turn it off. While it is on your prompt shows <mortal>.

While mortal mode is on:
  - spells use your spell slots and recover over time like anyone else's
  - you must know a spell or skill, and meet its class and alignment limits,
    to use it
  - gear restrictions (class, race, alignment, no-take) apply to you
  - carry weight and capacity limits apply
  - spells have a cast wind-up and you are held back after a broken-off cast
  - spells that cannot be cast in combat are refused while you fight

Your rank, commands and permissions do not change: goto, stat, users and every
other staff command still work, and you still see and enter god zones. Mortal
mode is not saved: it survives a dropped link while you are fighting (you
reconnect to the same character) and taking over your own body, but a normal
quit or logout resets it, so you start each fresh login with it off.

See also: HOLYLIGHT, SPELLS, SCORE$help$,
      min_level = 100,
      category = 'command',
      usage = 'mortal',
      source_file = 'data/help/mortal.md',
      updated_at = now()
    WHERE id = v_id
      AND (keywords, title, content, min_level, category, usage, source_file)
          IS DISTINCT FROM (ARRAY['mortal', 'mortal mode']::text[], 'Mortal mode', $help$MORTAL switches you between playing as an immortal and playing under mortal
rules, so you can retest what players experience. Type it once to turn mortal
mode on and again to turn it off. While it is on your prompt shows <mortal>.

While mortal mode is on:
  - spells use your spell slots and recover over time like anyone else's
  - you must know a spell or skill, and meet its class and alignment limits,
    to use it
  - gear restrictions (class, race, alignment, no-take) apply to you
  - carry weight and capacity limits apply
  - spells have a cast wind-up and you are held back after a broken-off cast
  - spells that cannot be cast in combat are refused while you fight

Your rank, commands and permissions do not change: goto, stat, users and every
other staff command still work, and you still see and enter god zones. Mortal
mode is not saved: it survives a dropped link while you are fighting (you
reconnect to the same character) and taking over your own body, but a normal
quit or logout resets it, so you start each fresh login with it off.

See also: HOLYLIGHT, SPELLS, SCORE$help$, 100, 'command', 'mortal', 'data/help/mortal.md');
  END IF;
END
$do$;
